using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using HarborValeGreybox.Driving;
using HarborValeGreybox.Racing;
namespace HarborValeGreybox.Garage {
public class FinchGarage:MonoBehaviour {
 public GarageCatalog Catalog{get;private set;}public DocksideTrialDirector Trial{get;private set;}public bool IsOpen{get;private set;}public string Message{get;private set;}public int AppliedStage{get;private set;}=-1;public int SelectedIndex{get;private set;}
 readonly Dictionary<string,string> requests=new Dictionary<string,string>();string appliedSignature;TextMesh sign;GarageShopView view;bool hudWasEnabled;public GarageShopView View=>view;
 public EngineTuneOffer[] Offers=>new[]{Catalog.offer,Catalog.gearboxOffer,Catalog.turboOffer,Catalog.intercoolerOffer};
 public static void Hook(){if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().name=="HarborVale_CityMap")new GameObject("Player garage | all prototype parts").AddComponent<FinchGarage>();}
 IEnumerator Start(){while(Trial==null||Trial.Definition==null){Trial=UnityEngine.Object.FindAnyObjectByType<DocksideTrialDirector>();yield return null;}var data=Resources.Load<TextAsset>("FinchGarageCatalog");if(data==null)throw new InvalidOperationException("Garage data missing");Catalog=JsonUtility.FromJson<GarageCatalog>(data.text);Catalog.Validate();if(Trial.Store!=null)ApplyInstalled();
  var g=new GameObject("Player garage sign");g.transform.SetParent(transform,false);g.transform.position=Catalog.Position+Vector3.up*5;sign=g.AddComponent<TextMesh>();sign.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");sign.fontSize=48;sign.characterSize=.15f;sign.anchor=TextAnchor.MiddleCenter;sign.alignment=TextAlignment.Center;sign.text="PLAYER GARAGE\nG — PARTS & TUNING";sign.color=new Color(.5f,.9f,1);g.GetComponent<Renderer>().sharedMaterial=sign.font.material;
 }
 public bool NearGarage=>Catalog!=null&&Trial!=null&&(Vector3.Distance(Trial.vehicle.transform.position,Catalog.Position)<26||HarborValeGreybox.Racing.PhysicalGarage.Instance?.InBay(Trial.vehicle.transform.position)==true);
 public bool Open(){if(Catalog==null||Trial.Store==null||Trial.Active||Trial.ShowingResult||!NearGarage||Trial.vehicle.SpeedKph>=5||!Trial.vehicle.playerInput)return false;try{Trial.Store.Refresh();ApplyInstalled();}catch(Exception e){Message="Saved progress could not be refreshed.";Debug.LogWarning(e.Message);return false;}Trial.vehicle.GetComponent<FinchDrivingHUD>()?.SetInspection(false);Trial.ExternalModalOpen=true;Trial.vehicle.controlsLocked=true;IsOpen=true;requests.Clear();SelectedIndex=0;Message=null;if(view==null)view=new GarageShopView(this);view.Open();var hud=Trial.vehicle.GetComponent<FinchDrivingHUD>();if(hud!=null){hudWasEnabled=hud.enabled;hud.enabled=false;}return true;}
 public void Close(){if(!IsOpen)return;IsOpen=false;view?.Close();FinchDrivingHUD hud=null;if(Trial!=null&&Trial.vehicle!=null)hud=Trial.vehicle.GetComponent<FinchDrivingHUD>();if(hud!=null)hud.enabled=hudWasEnabled;if(Trial!=null){Trial.ExternalModalOpen=false;if(Trial.vehicle!=null)Trial.vehicle.controlsLocked=false;}Message=null;}
 public void Select(int index){SelectedIndex=Mathf.Clamp(index,0,Offers.Length-1);Message=null;}
 public bool Purchase()=>BuyPart(Catalog.offer);
 public bool BuySelected()=>BuyPart(Offers[SelectedIndex]);
 public bool BuyPart(EngineTuneOffer offer){if(!IsOpen||Trial.Store==null)return false;try{if(!requests.TryGetValue(offer.PartId,out var id)){id=Guid.NewGuid().ToString("N");requests[offer.PartId]=id;}Trial.Store.PurchasePart(id,offer,offer.price,out bool duplicate);ApplyInstalled();Message=duplicate?"Already saved and installed.":offer.displayName+" installed. Payment and parts saved.";return true;}catch(Exception e){ApplyInstalled();Message=e is InvalidOperationException?e.Message:"Could not save. No new part was installed; retry.";Debug.LogWarning("Garage purchase: "+e.Message);return false;}}
 public void ApplyInstalled(){if(Trial.Store==null)return;if(Trial.Store.Profile.version>=7){UnityEngine.Object.FindAnyObjectByType<HarborValeGreybox.Workshop.ExpandedWorkshop>()?.SyncCareer();return;}var p=Trial.Store.Profile;string signature=p.engineStage+"/"+p.gearboxStage+"/"+p.intercoolerStage;if(signature==appliedSignature)return;Trial.vehicle.InstallPowertrain(Catalog.DefinitionFor(p),p.engineStage);AppliedStage=p.engineStage;appliedSignature=signature;UnityEngine.Object.FindAnyObjectByType<HarborValeGreybox.Workshop.ExpandedWorkshop>()?.SyncCareer();}
 void Update(){if(UnityEngine.Object.FindAnyObjectByType<HarborValeGreybox.Workshop.ExpandedWorkshop>()?.Ready==true)return;if(Catalog==null||Trial==null)return;if(IsOpen&&view!=null&&view.Typing){if(FinchInput.Shortcut(KeyCode.Escape))view.EndSearch();return;}if(FinchInput.Shortcut(KeyCode.G)){if(IsOpen)Close();else Open();}else if(IsOpen&&FinchInput.Shortcut(KeyCode.Escape))Close();else if(IsOpen&&FinchInput.Shortcut(KeyCode.DownArrow))view.Advance(1);else if(IsOpen&&FinchInput.Shortcut(KeyCode.UpArrow))view.Advance(-1);else if(IsOpen&&FinchInput.Shortcut(KeyCode.Return)&&view.Visible().Count>0)BuySelected();}
 void LateUpdate(){if(sign!=null){sign.gameObject.SetActive(!IsOpen&&HarborValeGreybox.Racing.PhysicalGarage.Instance?.Ready!=true);if(Camera.main!=null)sign.transform.rotation=Camera.main.transform.rotation;}}
 void OnGUI(){if(Catalog==null||Trial==null||Trial.Store==null)return;if(IsOpen){view?.Draw();return;}if(UnityEngine.Object.FindAnyObjectByType<HarborValeGreybox.Workshop.ExpandedWorkshop>()?.Ready==true)return;if(NearGarage&&!Trial.Active&&!Trial.ShowingResult&&Trial.vehicle.playerInput)GUI.Box(new Rect(16,128,690,26),Trial.vehicle.SpeedKph<5?"G — PLAYER GARAGE | Parts, tuning and your current build":"Slow down to enter the player garage");}
 static void Plot(Rect r,FinchDefinition d,bool off,Color color){var values=off?d.offBoostTorque:d.torque;Color previous=GUI.color;var matrix=GUI.matrix;GUI.color=color;for(int i=1;i<d.rpm.Length;i++){Vector2 a=new Vector2(r.x+10+(d.rpm[i-1]-900)/5600*(r.width-20),r.yMax-8-values[i-1]/180*(r.height-16)),b=new Vector2(r.x+10+(d.rpm[i]-900)/5600*(r.width-20),r.yMax-8-values[i]/180*(r.height-16));GUIUtility.RotateAroundPivot(Mathf.Atan2(b.y-a.y,b.x-a.x)*Mathf.Rad2Deg,a);GUI.DrawTexture(new Rect(a.x,a.y,Vector2.Distance(a,b),2),Texture2D.whiteTexture);GUI.matrix=matrix;}GUI.color=previous;}
 void OnDestroy(){if(IsOpen)Close();view?.Dispose();}
}
}
